 public TextSnapshot Data=new TextSnapshot{App="word",DocumentId="doc",TargetId="selection",Text="one\ntwo\nuntouched",FormatHash="plain",SurroundingHash="outside",Blocks=new List<TextBlock>{new TextBlock{Id="p1",Text="one",FormatHash="a",Editable=true},new TextBlock{Id="p2",Text="two",FormatHash="b",Editable=true},new TextBlock{Id="p3",Text="untouched",FormatHash="c",Editable=true}}};
 public int Writes;public bool ChangeOther,FailSecond,AutoResize;
 public TextSnapshot Capture()=>Wire.Clone(Data);
 public TextSnapshot Read(TextSnapshot binding){Data.Text=string.Join("\n",Data.Blocks.Select(b=>b.Text));return Wire.Clone(Data);}
 public void Replace(TextSnapshot binding,string text)=>throw new Exception("single write unsupported in fixture");
 public void ReplaceBlocks(TextSnapshot binding,IReadOnlyList<TextOperation> operations){foreach(var op in operations){Writes++;if(FailSecond&&Writes==2)throw new Exception("COM failure");Data.Blocks.Single(b=>b.Id==op.BlockId).Text=op.Text;}if(ChangeOther)Data.Blocks[2].Text="unexpected";if(AutoResize)foreach(var block in Data.Blocks)block.SourceLayoutHash="Office AutoSize adjusted height";}
 public object ReadOutline()=>new {readOnly=true};
}

sealed class FakeAutomationPort:IOfficeAutomationPort {public string Text="original";public int Writes;public bool Corrupt;public Exception WriteFault;public Action OnWrite;public void CheckSource(){}public object Execute(OfficeStep step,bool readOnly){if(step.Action=="set"){if(readOnly)throw new Exception("write in read");if(WriteFault!=null)throw WriteFault;Text=Corrupt?"bad":step.Value.Value<string>();Writes++;OnWrite?.Invoke();return new{applied=true};}return Text;}}
sealed class ThreadBoundAutomationPort:IOfficeAutomationPort {readonly int owner=Thread.CurrentThread.ManagedThreadId;public readonly FakeAutomationPort Inner=new FakeAutomationPort();public void CheckSource(){if(Thread.CurrentThread.ManagedThreadId!=owner)throw new OfficeFault("office_thread_required",invocationStarted:false);}public object Execute(OfficeStep step,bool readOnly){CheckSource();return Inner.Execute(step,readOnly);}}
sealed class FakeCreationPort:IDocumentCreationPort,IDocumentCreationState {public bool CreatedDocumentExists=>Data!=null;public bool PreCallFault;public DocumentDraft Data;public int Creates;public bool Fail,Corrupt;public string CreatedName=>"새 문서";public void CheckSource(){}public void Create(CreationPlan plan,CancellationToken token){if(PreCallFault)throw new OfficeFault("office_member_not_found","Add",unchecked((int)0x80020003),false);Creates++;Data=Wire.Clone(plan.Content);if(Fail)throw new Exception("COM failed");if(Corrupt)Data.Paragraphs[0].Text="unexpected";}public DocumentDraft ReadCreated()=>Wire.Clone(Data);}

sealed class FakeCellPort:IOfficeAutomationPort {
 public object Value;public string Formula,Format="General",Sheet,ActiveSheet="first";public bool HasFormula,CorruptLiteral,CorruptValue;public int Writes,Reads;
 public void CheckSource(){}
 public object Execute(OfficeStep step,bool readOnly){
  if(step.Action=="set"){if(readOnly)throw new Exception("write in read");Writes++;if(step.Member=="NumberFormat")Format=(string)step.Value;else if(step.Member=="Formula"){Formula=((string)step.Value).Replace("sum(","SUM(");if(CorruptLiteral)Formula=Formula.Replace("Yes","YES");HasFormula=true;}else if(step.Member=="Value2"){Value=CorruptValue?(object)999:step.Value.Type==JTokenType.Null?null:((JValue)step.Value).Value;Formula=Convert.ToString(Value);HasFormula=false;}return null;}
  Reads++;switch(step.Member){case "ActiveSheet":Sheet=ActiveSheet;return null;case "Name":return Sheet;case "Item":Sheet=Convert.ToString(step.Args[0]);return null;case "Value2":return Value;case "Formula":return Formula;case "NumberFormat":return Format;case "HasFormula":return HasFormula;default:return null;}
 }
}

class FakeMergePort:IOfficeAutomationPort {
 public string Title="title",Other;public bool Merged,Corrupt;public int Writes;
 public void CheckSource(){}
 public object Execute(OfficeStep step,bool readOnly){
  if(step.Action=="call"&&(step.Member=="Merge"||step.Member=="UnMerge")){if(readOnly||step.Target!="merge_range")throw new Exception("invalid merge");Writes++;Merged=step.Member=="Merge";if(Corrupt)Title="lost";return null;}
  switch(step.Member){case "Name":return "Sheet1";case "MergeCells":return Merged;case "Value2":case "Formula":return step.Target=="merge_top"?(object)Title:new object[,]{{Title,Other}};default:return null;}
 }
}

sealed class CountPort:IOfficeAutomationPort {
 public int Count=1,Writes;public string Value="original";public bool CorruptCount;
 public void CheckSource(){}
 public object Execute(OfficeStep step,bool readOnly){
  if(step.Member=="Worksheets")return new{reference=step.Id};
  if(step.Member=="Count")return (double)Count;
  if(step.Action=="get")return Value;
  if(readOnly)throw new Exception("read attempted write");Writes++;
  if(step.Action=="set"){Value=(string)step.Value;return new{applied=true};}
  Count+=(step.Args.Count>2?(int)step.Args[2]:1)+(CorruptCount?1:0);return new{reference=step.Id};
 }
}

sealed class FormatPort:IOfficeAutomationPort {
 public string Sheet,Address,Format="General",Formula="=SUM(A1:A3)";public int Value=42,Writes,Reads;public bool Bold,Wrap,Corrupt;
 public void CheckSource(){}
 public double ColumnWidth=8.43,RowHeight=15;
 public object Execute(OfficeStep step,bool readOnly){if(step.Action=="set"){Writes++;if(Corrupt)return new{applied=true};if(step.Member=="NumberFormat")Format=(string)step.Value;else if(step.Member=="Font.Bold")Bold=(bool)step.Value;else if(step.Member=="WrapText")Wrap=(bool)step.Value;else if(step.Member=="ColumnWidth")ColumnWidth=Math.Round((double)step.Value*16)/16;else if(step.Member=="RowHeight")RowHeight=Math.Round((double)step.Value*2)/2;else throw new Exception("unexpected write");return new{applied=true};}Reads++;switch(step.Member){case "Worksheets":case "ActiveSheet":return new{reference=step.Id};case "Item":Sheet=(string)step.Args[0];return new{reference=step.Id};case "Name":return "active";case "Range":Address=(string)step.Args[0];return new{reference=step.Id};case "Value2":return Value;case "Formula":return Formula;case "NumberFormat":return Format;case "Font.Bold":return Bold;case "WrapText":return Wrap;case "ColumnWidth":return ColumnWidth;case "RowHeight":return RowHeight;default:throw new Exception("unexpected read");}}
}

sealed class WorksheetPort:IOfficeAutomationPort {
 public sealed class Sheet {public string Name;}
 public readonly List<Sheet> Sheets=new List<Sheet>(),All=new List<Sheet>();readonly Dictionary<string,object> handles=new Dictionary<string,object>();public int Writes;public bool CorruptName;
 public WorksheetPort(){AddExisting("One");AddExisting("Two");}
 public void AddExisting(string name){var sheet=new Sheet{Name=name};Sheets.Add(sheet);All.Add(sheet);}
 public void AddChart(string name)=>All.Add(new Sheet{Name=name});
 public void CheckSource(){}
 public object Execute(OfficeStep step,bool readOnly){object result;object target=step.Target=="document"?null:handles[step.Target];
  if(step.Member=="Worksheets")result=Sheets;
  else if(step.Member=="Sheets")result=All;
  else if(step.Member=="Count")result=((List<Sheet>)target).Count;
  else if(step.Member=="Item")result=((List<Sheet>)target)[(int)step.Args[0]-1];
  else if(step.Member=="Name"){if(!(target is Sheet sheet))throw new OfficeFault("office_member_not_found","Name",invocationStarted:false);if(step.Action=="set"){Writes++;if(!CorruptName)sheet.Name=(string)step.Value;return new{applied=true};}result=sheet.Name;}
  else if(step.Member=="Add"){if(readOnly)throw new Exception("write in read");Writes++;AddExisting("new");result=Sheets.Last();}
  else throw new Exception("unexpected worksheet operation");
  if(result is Sheet||result is List<Sheet>){handles[step.Id]=result;return new{reference=step.Id};}return result;
 }
}

sealed class SessionWorker : IOfficeWorker {
 public event Action<JObject> Message;public event Action Disconnected;public int Listens;public bool Disposed;public List<JObject> Sent=new List<JObject>();
 public void Listen(){Listens++;}public void Send(object message){Sent.Add(Wire.Object(message));}public void Emit(string message){Message?.Invoke(Wire.Parse(message));}public void Drop(){Disconnected?.Invoke();}public void Dispose(){Disposed=true;}
}
